        }
        if ($uploadError === UPLOAD_ERR_INI_SIZE || $uploadError === UPLOAD_ERR_FORM_SIZE || ((int)($file['size'] ?? 0) > $maxBytes)) {
            echo json_encode(['success' => false, 'message' => t('custom_commands_import_err_too_large')]);
            exit;
        }
        if ($uploadError !== UPLOAD_ERR_OK) {
